CREATE OR REPLACE FUNCTION public.create_advisory_matter_with_number(p_client_id uuid, p_title text, p_matter_type text, p_retainer_type text, p_status text, p_responsible_lawyer text, p_start_date date, p_end_date date, p_monthly_retainer_amount numeric, p_scope_of_work text, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  created_matter public.advisory_matters%rowtype;
begin
  if auth.uid() is null or public.can_create_advisory_matter() is distinct from true then
    raise exception 'ADVISORY_CREATE_PERMISSION_DENIED' using errcode = '42501';
  end if;
  -- Existing form's required fields. Retainer visibility/edit logic stays in its
  -- existing workflow; this RPC neither adds Finance privileges nor changes it.
  if p_client_id is null or nullif(btrim(p_title), '') is null
    or nullif(btrim(p_matter_type), '') is null then
    raise exception 'ADVISORY_REQUIRED_FIELDS_MISSING' using errcode = '22023';
  end if;
  insert into public.advisory_matters (
    client_id, matter_no, title, matter_type, retainer_type, status,
    responsible_lawyer, start_date, end_date, monthly_retainer_amount,
    scope_of_work, note
  ) values (
    p_client_id, public.generate_advisory_matter_no(), p_title, p_matter_type,
    p_retainer_type, p_status, p_responsible_lawyer, p_start_date, p_end_date,
    p_monthly_retainer_amount, p_scope_of_work, p_note
  ) returning * into created_matter;
  return to_jsonb(created_matter);
end;
$function$

CREATE OR REPLACE FUNCTION public.payout_profile_delete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if exists(select 1 from public.finance_payable_entitlements where recipient_type='user' and recipient_id=old.id)
 then raise exception 'PAYABLE_RECIPIENT_HISTORY_REQUIRED'; end if;
 return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.people_profile_update_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 -- Only the private completion RPC / nested Auth reset trigger can change this
 -- field. Preserve the original 073 guard byte-for-byte for every other edit.
 if new.must_change_password is distinct from old.must_change_password then
  if (to_jsonb(new)-'must_change_password') is distinct from (to_jsonb(old)-'must_change_password')
    or current_setting('people.password_target',true) is distinct from new.id::text
    or not (pg_trigger_depth()>1 or current_setting('role',true)='service_role')
  then raise exception 'PASSWORD_STATE_MANAGED'; end if;
  return new;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('people-admin',0));
 if not public.people_is_active_admin() then raise exception 'FORBIDDEN'; end if;
 if new.id is distinct from old.id or new.email is distinct from old.email then raise exception 'INVALID_INPUT'; end if;
 if old.id=auth.uid() and (new.role is distinct from 'admin' or new.active is not true) then raise exception 'SELF_PROTECTION'; end if;
 if new.active is not true or new.account_type is distinct from 'operational' then new.assignable:=false; end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_finance_billable_charge_permission_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1
    from public.user_profiles
    where id = auth.uid()
      and active = true
      and role = 'admin'
  ) then
    raise exception 'Only an active Admin can change Billable Charge authority';
  end if;
  return new;
end;
$function$

