CREATE OR REPLACE FUNCTION public.protect_finance_receipt_permission_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' and not (new.can_view_finance_receipts or new.can_manage_finance_receipts
    or new.can_issue_finance_receipts or new.can_void_finance_receipts) then return new; end if;
  if not exists (select 1 from public.user_profiles where id = auth.uid() and active and role = 'admin')
  then raise exception 'Only an active Admin can change Receipt authority'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_finance_tax_invoice_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' and not(new.can_view_finance_tax_invoices or new.can_manage_finance_tax_invoices or new.can_issue_finance_tax_invoices) then return new; end if;
  if not exists(select 1 from public.user_profiles where id=auth.uid() and active and role='admin')
  then raise exception 'TAX_INVOICE_PERMISSION_ADMIN_REQUIRED'; end if;
  return new;
end;
$function$
